* { box-sizing: border-box; }
[hidden] { display: none !important; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  color: #1f2933;
  background: #f5f7fa;
}

header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem 2rem;
  padding: 0.75rem 1.5rem;
  background: #243b53;
  color: #fff;
}
header h1 { margin: 0; font-size: 1.4rem; }
nav { display: flex; gap: 0.5rem; }
nav a {
  color: #d9e2ec;
  text-decoration: none;
  padding: 0.35rem 0.75rem;
  border-radius: 4px;
}
nav a.active { background: #486581; color: #fff; }
.balance { margin-left: auto; font-weight: 600; }

main { max-width: 960px; margin: 0 auto; padding: 1rem 1.5rem 3rem; }

.form, .toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 0.75rem;
  margin-bottom: 1rem;
}
label { display: flex; flex-direction: column; font-size: 0.85rem; gap: 0.2rem; }
label.file { flex-direction: row; align-items: center; gap: 0.4rem; }
input, select, button { font: inherit; padding: 0.35rem 0.5rem; }
button {
  border: 1px solid #829ab1;
  border-radius: 4px;
  background: #fff;
  cursor: pointer;
}
button:hover:not(:disabled) { background: #e4e7eb; }
button:disabled { opacity: 0.5; cursor: default; }

table { width: 100%; border-collapse: collapse; background: #fff; margin-bottom: 1rem; }
th, td { padding: 0.45rem 0.6rem; border-bottom: 1px solid #e4e7eb; text-align: left; }
th { background: #f0f4f8; }
th.sortable { cursor: pointer; text-decoration: underline dotted; }
td.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }
td.neg { color: #c62828; }
td.pos { color: #2e7d32; }
tr.over { background: #ffebee; }
tr.over td { color: #b71c1c; font-weight: 600; }

canvas { display: block; max-width: 100%; background: #fff; border: 1px solid #e4e7eb; }

